selector_to_html = {"a[href=\"#pyskyfire.pump.impeller.Impeller.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.pump.impeller.Impeller\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Impeller</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">shaft_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_hub_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_efficiency</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta2_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">psi</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fT</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">phi1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta1_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">incidence_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_prewhirl</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wrap_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">volumetric_efficiency</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tip_clearance</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">meridional</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axial_length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_settings</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">splitter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Size a radial impeller; call build_geometry() to generate pyTurbo surfaces.</p><p>Required lengths are in metres. <code class=\"docutils literal notranslate\"><span class=\"pre\">blade_thickness</span></code> is total section-normal\nbody thickness: a float or function of chord_fraction, span_fraction, x, r.\nAngle and prewhirl functions accept span_fraction, x, r. Span runs hub to\nblade tip, including when tip clearance is present. <code class=\"docutils literal notranslate\"><span class=\"pre\">phi1</span></code> refers to the\nunblocked inlet annulus, and d1 overrides its sizing equation.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> is the total head at the impeller outlet and <code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_efficiency</span></code>\nthe impeller\u2019s own (see the module notes); it is a supplied assumption,\nnever predicted here. The design is closed on one quantity. By default\n<code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> is solved and the outlet diameter comes from one of <code class=\"docutils literal notranslate\"><span class=\"pre\">psi</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">u2</span></code> or a supplied <code class=\"docutils literal notranslate\"><span class=\"pre\">meridional</span></code>, or failing all of them from\nEq. (3.26) at <code class=\"docutils literal notranslate\"><span class=\"pre\">fT</span></code>. Give <code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> instead and <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code> is solved. Giving\nboth over-specifies the wheel. The solved angle is the one below the peak\nof the swirl it can deliver: at low specific speed that peak is broad and\nflat, and a head above it cannot be had at any angle, which is reported\nwith the head coefficient that can.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">blade_count</span></code> is always an input. G\u00fclich rejects empirical blade-count\nformulas as likely to violate the criteria that actually set it: pressure\npulsations against the collector, blade loading, head-curve stability.\nSplitters do not count toward it in the slip prediction.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">incidence_deg</span></code> means metal angle minus unblocked relative inlet flow\nangle. No leakage is assumed for volumetric_efficiency=1. <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> defaults\nto Eq. (7.1).</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code> is which way the wheel turns about its own +x shaft, and only\nmirrors the blades: every velocity triangle is a magnitude in the rotating\nframe and is the same either way. It has to match the sense of the volute\ncollecting the discharge, once both are placed.\nCreate a new Impeller to change design inputs; build_geometry can be repeated\nat different numerical resolutions using the same resolved definition.</p></dd>", "a[href=\"#pyskyfire.pump.impeller.Impeller.from_pressure_rise\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller.from_pressure_rise\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_pressure_rise</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">dp</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">**</span></span><span class=\"n\"><span class=\"pre\">kwargs</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire-pump-impeller-impeller\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump.impeller.Impeller<a class=\"headerlink\" href=\"#pyskyfire-pump-impeller-impeller\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.pump.impeller.Impeller.build_geometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller.build_geometry\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_geometry</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">33</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chord_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">129</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Generate surfaces lazily. Returns and stores an ImpellerGeometry.</p></dd>", "a[href=\"#pyskyfire.pump.impeller.Impeller.blade_power\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller.blade_power\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">blade_power</span></span></dt><dd><p>Power the blades put into the fluid [W], or None without <code class=\"docutils literal notranslate\"><span class=\"pre\">rho</span></code>.</p><p>Every kilogram through the impeller, leakage included, takes the full\nblade work g*H/eta_h. Disk friction and the bearings are charged by the\ncomponents that own them, not here.</p></dd>", "a[href=\"#pyskyfire.pump.impeller.Impeller.from_duty\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller.from_duty\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_duty</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">duty</span></span></em>, <em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">**</span></span><span class=\"n\"><span class=\"pre\">kwargs</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Size for a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">PumpDuty</span></code>: its inlet flow, head and speed.</p><p>The inlet density, where the duty knows one, is what the blade power is\nreported at.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
